def comps(g,val):
    seen=set(); n=0; sizes=[]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and (i,j) not in seen:
                n+=1; stack=[(i,j)]; seen.add((i,j)); s=0
                while stack:
                    a,b=stack.pop(); s+=1
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==val and (x,y) not in seen:
                            seen.add((x,y)); stack.append((x,y))
                sizes.append(s)
    return n,sizes
